const path = require('path');

const NON_AI_VIDEO_PROVIDERS = new Set(['slideshow', 'simulation']);
const NON_AI_NARRATION_PROVIDERS = new Set(['simulation']);
const IMAGE_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg', '.webp']);

/**
 * Lists which parts of a production were generated by AI. YouTube requires the
 * altered/synthetic media disclosure for realistic AI voice, imagery or video,
 * so any AI-generated component makes the disclosure mandatory.
 */
function detectSyntheticMedia(productionData = {}) {
  const assets = productionData.assets || {};
  const reasons = [];

  const videoProvider = assets.finalVideo?.provider?.actualProvider;
  if (videoProvider && !NON_AI_VIDEO_PROVIDERS.has(videoProvider)) reasons.push('ai_video');

  const audio = assets.audio || {};
  if (audio.status === 'ready' && audio.provider && !NON_AI_NARRATION_PROVIDERS.has(audio.provider)) {
    reasons.push('ai_voice');
  }

  // Real image files in visualAssets only come from image models; simulated
  // placeholders are written as .info files.
  const visuals = assets.video?.visualAssets || [];
  if (visuals.some(file => IMAGE_EXTENSIONS.has(path.extname(String(file)).toLowerCase()))) {
    reasons.push('ai_images');
  }

  return { containsSyntheticMedia: reasons.length > 0, reasons };
}

module.exports = { detectSyntheticMedia };
